"""Render the Python color library into database/seed_colors.sql.

Run:  python scripts/generate_color_seed.py
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from src.core.color_library import COLOR_LIBRARY  # noqa: E402


def render() -> str:
    rows = ",\n".join(
        f"  ('{c.name.replace(chr(39), chr(39) * 2)}', '{c.hex}', '{c.family}', {'true' if c.is_neutral else 'false'})"
        for c in COLOR_LIBRARY
    )
    return (
        "-- Generated by scripts/generate_color_seed.py from src/core/color_library.py. Do not edit by hand.\n"
        "insert into public.colors (name, hex, family, is_neutral) values\n"
        f"{rows}\n"
        "on conflict (name) do update set hex = excluded.hex, family = excluded.family, is_neutral = excluded.is_neutral;\n"
    )


def main() -> None:
    out = ROOT / "database" / "seed_colors.sql"
    out.write_text(render(), encoding="utf-8")
    print(f"wrote {len(COLOR_LIBRARY)} colors to {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
